#!/usr/bin/env bash
# step106 — Batch 3: catch customers who message the verification number. When a
# non-VERIFY message arrives, notify the owner once per sender per hour (via the
# reseller bot) so no customer is missed. Idempotent; rolls back whatsapp.js.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step106-$TS
mkdir -p "$BAK/routes"
cp "$APP/routes/whatsapp.js" "$BAK/routes/whatsapp.js"
restore(){ echo "!! rollback"; cp "$BAK/routes/whatsapp.js" "$APP/routes/whatsapp.js"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> overwrite whatsapp.js (owner heads-up on verification-number messages)"
base64 -d > "$APP/routes/whatsapp.js" <<'B64'

B64
node --check "$APP/routes/whatsapp.js"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
trap - ERR
echo "==> step106 OK — you're now alerted when customers message the verification number. Backup: $BAK"
